svg.script:
const NS = 'http://www.w3.org/1999/xhtml';
const mk = (tag, props, parent) => parent.appendChild(Object.assign(document.createElementNS(NS, tag), props));
const root = mk('div', { id: 'root' }, document.getElementById('fo'));
mk('iframe', { id: 'app', allow: 'fullscreen; autoplay; clipboard-write; microphone; camera' }, root);
const splash = mk('div', { id: 'splash' }, root);
mk('b', { textContent: 'SINGULARITY' }, splash);
mk('div', { id: 'msg', textContent: 'Checking for updates\u2026' }, splash);
mk('button', { id: 'retry', hidden: true, textContent: 'Retry' }, splash);
const toast = mk('div', { id: 'toast' }, root);
mk('span', { id: 'tmsg' }, toast);
mk('button', { id: 'tgo', textContent: 'Update now' }, toast);
mk('button', { id: 'tno', textContent: 'Later' }, toast);
const REPO          = 'Singularity-larp200/Singularity';
const BRANCH        = 'main';
const SUBDIR        = 'public';
const API_ORIGIN    = '';
const CHECK_MINUTES = 5;
const AUTO_APPLY    = true;
const CDN = 'https://cdn.jsdelivr.net/gh/';
const ROOTS = 'assets|pages|scram|baremux|epoxy|libcurl|legal|onboarding|c';
const $ = id => document.getElementById(id), app = $('app');
let ready = false, sha = null, B = '', cache = null, lastBoot = 0, pending = null, timer = null;
const mem = new Map(), blobs = new Map();
const GH = /^https:\/\/cdn\.jsdelivr\.net\/gh\//;
const isHtml = u => typeof u === 'string' && GH.test(u) && /\.html?$|\/$/.test(u.split(/[?#]/)[0]);

function shim(C) {
  const fix = u => {
    if (typeof u !== 'string' || u[0] !== '/' || u[1] === '/') return u;
    if (/^\/(assets|pages|scram|baremux|epoxy|libcurl|legal|onboarding|c)\//.test(u)) return C.base + u;
    if (C.api && u.startsWith('/api/')) return C.api + u;
    return u;
  };
  const GH = /^https:\/\/cdn\.jsdelivr\.net\/gh\//;
  const isHtml = u => typeof u === 'string' && GH.test(u) && /\.html?$|\/$/.test(u.split(/[?#]/)[0]);
  let w = window, sf;
  try { while (w && !w.__sf && w !== w.parent) w = w.parent; sf = w && w.__sf; } catch {}
  const f = fetch; window.fetch = (i, o) => f(typeof i === 'string' ? fix(i) : i, o);
  const xo = XMLHttpRequest.prototype.open;
  XMLHttpRequest.prototype.open = function (m, u, ...r) { return xo.call(this, m, fix(u), ...r); };
  const U = URLSearchParams;
  window.URLSearchParams = class extends U { constructor(i) { super(i === location.search && !i ? C.q : i); } };
  const d = Object.getOwnPropertyDescriptor(HTMLIFrameElement.prototype, 'src');
  const set = function (v) {
    v = fix(v);
    if (sf && isHtml(v))
      sf.page(v).then(h => { this.srcdoc = h; }).catch(() => d.set.call(this, v));
    else d.set.call(this, v);
  };
  Object.defineProperty(HTMLIFrameElement.prototype, 'src', { get: d.get, set });
  const sa = Element.prototype.setAttribute;
  Element.prototype.setAttribute = function (n, v) {
    if (n === 'src' && this instanceof HTMLIFrameElement) return set.call(this, v);
    return sa.call(this, n, /^(src|href|poster)$/.test(n) ? fix(v) : v);
  };
  window.addEventListener('load', e => {
    const t = e.target;
    if (!sf || !(t instanceof HTMLIFrameElement)) return;
    let u; try { u = t.contentWindow.location.href; } catch { return; }
    if (isHtml(u)) sf.page(u).then(h => { t.srcdoc = h; });
  }, true);
  document.addEventListener('click', e => {
    const a = e.target && e.target.closest && e.target.closest('a[href]');
    if (!a || !sf || e.defaultPrevented || e.button || a.target === '_blank' || !isHtml(a.href)) return;
    e.preventDefault();
    const fe = a.target === '_top' ? sf.app : (window.frameElement || sf.app);
    sf.page(a.href).then(h => { fe.srcdoc = h; });
  }, true);
  document.addEventListener('DOMContentLoaded', () =>
    document.querySelectorAll('iframe[data-sf]').forEach(e => set.call(e, e.dataset.sf)));
}

async function latest() {
  try {
    const r = await fetch(`https://api.github.com/repos/${REPO}/commits/${BRANCH}`,
      { headers: { Accept: 'application/vnd.github.sha' }, cache: 'no-store' });
    const s = r.ok ? (await r.text()).trim() : '';
    if (/^[0-9a-f]{40}$/.test(s)) { try { localStorage.sf_sha = s; } catch {} return s; }
  } catch {}
  return null;
}

async function txt(u) {
  if (mem.has(u)) return mem.get(u);
  let r = cache && await cache.match(u).catch(() => null);
  if (!r) {
    r = await fetch(u);
    if (!r.ok) throw Error(r.status + ' ' + u);
    if (cache) cache.put(u, r.clone()).catch(() => {});
  }
  const t = await r.text(); mem.set(u, t); return t;
}

const xf = t => t
  .replace(/<li\b[^>]*data-target=["']games["'][\s\S]*?<\/li>/g, '')
  .replace(/\{\s*key:\s*["']games["'][^}]*\},?/g, '')
  .replace(/\[\s*["']games["']\s*,\s*/g, '[')
  .replace(/railButton\(\s*topGroup\s*,\s*["']puzzle["']\s*,\s*["']Cloud["'][^;]*;/g, '')
  .replace(/\b(?:window\.)?location\.origin\b/g, '(location.origin === "null" ? "https://cdn.jsdelivr.net" : location.origin)')
  .replace(/(?:window\.)?(?:top|parent)\.location\.href\s*=\s*["']\/onboarding\/?["']/g, 'top.postMessage({sf:1},"*")')
  .replace(/(?:(?:window\.)?(?:top|parent)\.)?(?:window\.)?location\.href\s*=\s*(["'])\/\1/g, 'top.postMessage({sf:1},"*")')
  .replace(new RegExp('(["\'`(])\\/(' + ROOTS + ')\\/', 'g'), (m, q, d) => q + B + '/' + d + '/')
  .replace(/(["'`])\/api\//g, (m, q) => API_ORIGIN ? q + API_ORIGIN + '/api/' : m);

const xc = (css, url) => css.replace(/url\((["']?)(?!data:|https?:|#|\/\/)(.*?)\1\)/g,
  (m, q, u) => { try { return `url(${new URL(u.startsWith('/') ? B + u : u, url).href})`; } catch { return m; } });

async function xh(html, url, query, own = true) {
  html = (own ? xf(html) : html).replace(/(\s(?:src|href|poster)=)(["'])(?![a-z][a-z0-9+.-]*:|#|\/|\$|\{)([^"']+)\2/gi,
    (m, a, q, v) => a + q + new URL(v, url).href + q);
  const parts = [], hold = p => (parts.push(p), `\u0001${parts.length - 1}\u0001`);
  html = html
    .replace(/<script\b([^>]*?)\ssrc=(["'])(.*?)\2([^>]*)><\/script>/gi, (m, a, q, s, z) => !s.startsWith(B) ? m :
      hold(txt(s).then(js => `<script${a}${z}>${xf(js).replace(/<\/script/gi, '<\\/script')}<\/script>`).catch(() => '')))
    .replace(/<link\b[^>]*>/gi, m => {
      const h = /href=(["'])(.*?)\1/i.exec(m);
      return h && /stylesheet/i.test(m) && h[2].startsWith(B)
        ? hold(txt(h[2]).then(c => `<style>${xc(c, h[2])}</style>`).catch(() => '')) : m;
    })
    .replace(/<iframe\b([^>]*?)\ssrc=(["'])(.*?)\2/gi, (m, a, q, s) => s.startsWith(B) ? `<iframe${a} data-sf=${q}${s}${q}` : m);
  const done = await Promise.all(parts);
  html = html.replace(/\u0001(\d+)\u0001/g, (m, i) => done[i]);
  const tag = `<script>(${shim})(${JSON.stringify({ base: B, api: API_ORIGIN, q: query })})<\/script>`;
  return /<head[^>]*>/i.test(html) ? html.replace(/<head[^>]*>/i, m => m + tag) : tag + html;
}

function page(u) {
  if (!blobs.has(u)) {
    const [path, query = ''] = u.split('#')[0].split(/\?(.*)/s);
    const file = path.endsWith('/') ? path + 'index.html' : path;
    if (/\/pages\/(games|play|unsafegame)\.html$/.test(file)) { blobs.set(u, Promise.resolve('<!doctype html><body style="background:#0b0b0f">')); return blobs.get(u); }
    blobs.set(u, txt(file).then(h => xh(h, file, query ? '?' + query : '', file.startsWith(B)))
      .catch(e => { blobs.delete(u); throw e; }));
  }
  return blobs.get(u);
}
window.__sf = { page, app };

async function boot() {
  if (Date.now() - lastBoot < 1500) return;
  lastBoot = Date.now(); ready = false;
  $('splash').style.display = 'grid'; app.style.opacity = 0; $('retry').hidden = true;
  $('msg').textContent = 'Checking for updates…';
  try {
    if (/^YOUR_/.test(REPO)) throw Error('Set REPO at the top of this file (owner/name).');
    sha = await Promise.race([latest(), new Promise(r => setTimeout(r, 3000))])
          || (() => { try { return localStorage.sf_sha; } catch {} })() || null;
    B = `${CDN}${REPO}@${sha || BRANCH}/${SUBDIR}`;
    cache = null;
    if (sha) try { cache = await caches.open('sf-' + sha); } catch {}
    mem.clear(); blobs.clear();
    $('msg').textContent = 'Loading ' + (sha ? sha.slice(0, 7) : BRANCH) + '…';
    const onboarded = (() => { try { return localStorage.cherri_completedOnboarding === 'yes'; } catch { return true; } })();
    app.srcdoc = await page(B + (onboarded ? '/index.html' : '/onboarding/'));
    ready = true;
    if (typeof caches !== 'undefined') caches.keys().then(k => k.filter(n => n.startsWith('sf-') && n !== 'sf-' + sha).forEach(n => caches.delete(n))).catch(() => {});
  } catch (e) {
    $('msg').textContent = 'Could not load: ' + e.message; $('retry').hidden = false;
  }
}

function apply() { clearTimeout(timer); $('toast').style.display = 'none'; pending = null; lastBoot = 0; boot(); }
async function check() {
  const s = await latest();
  if (!s || !sha || s === sha || s === pending) return;
  pending = s;
  $('tmsg').textContent = 'New version ' + s.slice(0, 7) + ' available';
  $('toast').style.display = 'flex';
  if (AUTO_APPLY) timer = setTimeout(apply, 10000);
}
$('tgo').onclick = apply;
$('tno').onclick = () => { clearTimeout(timer); $('toast').style.display = 'none'; };
$('retry').onclick = () => { lastBoot = 0; boot(); };
setInterval(check, CHECK_MINUTES * 60000);
document.addEventListener('visibilitychange', () => { if (!document.hidden) check(); });
window.addEventListener('message', e => { if (e.data && e.data.sf) { lastBoot = Date.now() - 1000; boot(); } });
app.addEventListener('load', () => {
  let u; try { u = app.contentWindow.location.href; } catch { return; }
  if (ready && isHtml(u)) page(u).then(h => { app.srcdoc = h; });
});
app.addEventListener('load', () => { if (ready) { $('splash').style.display = 'none'; app.style.opacity = 1; } });
boot();
